import RNA
import random
import sys

# My balanced 123-char reconstruction (replaced pos 121 ')' with '.')
target = ".(((.(((...(((.(((...))).(((....))).)))...(((.(((....))).(((...))).)))...(((.(((....))).(((...))).)))...)).)).((...))).))).."
d = 0
for c in target:
    if c == '(':
        d += 1
    elif c == ')':
        d -= 1
print('len:', len(target), 'open:', target.count('('), 'close:', target.count(')'), 'final:', d)
assert d == 0

n = len(target)
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

COMP = {'A': 'U', 'U': 'A', 'G': 'C', 'C': 'G'}

def fold(s):
    fc = RNA.fold_compound(s)
    return fc.mfe()

def diagnose(s):
    m, e = fold(s)
    mm = sum(1 for a, b in zip(m, target) if a != b)
    return mm, m, e

def init(seed):
    rng = random.Random(seed)
    s = []
    for i in range(n):
        if i in pairs:
            if rng.random() < 0.5:
                s.append('G')
            else:
                s.append('C')
        else:
            s.append(rng.choice('AU'))
    return ''.join(s)

best = None
bm = 999
import math
for trial in range(2000):
    rng = random.Random(trial * 7 + 1)
    seq = init(trial)
    mm, _, _ = diagnose(seq)
    cur = mm
    for it in range(800):
        T = max(0.05, 1.5 * (1 - it / 800))
        s = list(seq)
        # pick a pair position or unpaired
        if rng.random() < 0.7:
            # mutate a pair
            i = rng.randint(0, n - 1)
            if i in pairs:
                j = pairs[i]
                choices = [(b, COMP[b]) for b in 'GCAU' if b != seq[i]]
                a, b = rng.choice(choices)
                s[i] = a
                s[j] = b
            else:
                s[i] = rng.choice([x for x in 'ACGU' if x != seq[i]])
        else:
            i = rng.randint(0, n - 1)
            s[i] = rng.choice([x for x in 'ACGU' if x != seq[i]])
        nseq = ''.join(s)
        nm, _, _ = diagnose(nseq)
        if nm < cur:
            seq = nseq
            cur = nm
        elif nm <= cur:
            seq = nseq
            cur = nm
        elif rng.random() < math.exp(-(nm - cur) / T):
            seq = nseq
            cur = nm
    if cur < bm:
        bm = cur
        best = seq
        sys.stdout.write('trial %d best_mm %d\n' % (trial, bm))
        sys.stdout.flush()
        if bm == 0:
            sys.stdout.write('SOLVED\n%s\n' % best)
            sys.stdout.flush()
            break

sys.stdout.write('FINAL best_mm %d\n%s\n' % (bm, best))
sys.stdout.flush()
PYEOF
echo "script ready"
